const INDEX_LOG = path.join(os.homedir(), '.claude', 'global-memory', 'transcripts', '.memsearch-index.log');
// When several sessions end in a cluster, each spawnSync below would otherwise
// block the full timeout waiting on memsearch's own lock and then time out. The
// lock is acquired ATOMICALLY (open 'wx') so only one winner indexes per cluster;
// late arrivals see EEXIST and skip immediately — that run covers their new
// content too. The owner PID is checked before a lock is reclaimed. Age is only
// a fallback for locks written by an older version that did not record a PID.
const LOCK_FILE = path.join(os.homedir(), '.claude', 'global-memory', 'transcripts', '.memsearch-index.lock');
const LOCK_STALE_MS = 5 * 60 * 1000;
// A single ETIMEDOUT is self-healing (the next session's incremental index
// catches up) and usually just means session-end contention — three fired on
// 2026-07-08 alone while the index stayed healthy. Only escalate to .errors.log
// after this many CONSECUTIVE timeouts; the count lives in a state file and any
// clean run resets it. Non-timeout failures still escalate immediately.
const TIMEOUT_STREAK_FILE = path.join(os.homedir(), '.claude', 'global-memory', 'transcripts', '.memsearch-timeout-streak');
// Raised 3 -> 6 on 2026-07-24: the nightly KeystoneOS-DailyBackup task now runs
// an uncapped full reindex and resets this counter, so heavy-day backlogs are
// guaranteed to clear overnight. Alarm only if even the nightly isn't keeping up.
const TIMEOUT_STREAK_THRESHOLD = 6;
// Signatures that mean "another writer holds milvus.db/LOCK", not "the database
// is damaged". Deliberately narrow: matched against the flock/lock-acquisition
// text, NOT against milvus-lite's wording "may not be compatible with Milvus
// Lite 3.x" — that same sentence is emitted for genuine incompatibility too, so
// matching it would mask real corruption as transient. A truly broken database
// produces none of these and still escalates immediately.
const LOCK_BUSY_RE = /DataDirLockedError|another process holds the lock|Resource temporarily unavailable|_acquire_lock|fcntl\.flock/i;
// macOS refuses to dlopen native libraries once shutdown starts ("code signature
// ... not valid for use in process: system is shutting down"). A session that
// ends during a restart hits this on onnxruntime's .so and memsearch rewords it
// as "requires onnxruntime. Install with: pip install". The install is fine;
// do not reinstall. Seen 2026-09-16 07:46:41, reboot at 07:46:56.
const SHUTDOWN_RE = /system is shutting down/i;

// The first "SomethingError: ..." line of a traceback. memsearch wraps the real
// failure in two more exceptions, so the first 300 chars of stderr are only
// "Traceback ... File ... import onnxruntime" and never reach the cause.
function rootCause(text) {
  const m = (text || '').match(/^[\w.]*(?:Error|Exception): .*$/m);
  return m ? m[0] : (text || '');
}

if (existing.length === 0) process.exit(0);

function isProcessAlive(pid) {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (e) {
    return e && e.code === 'EPERM';
  }
}

// --- Acquire the lock atomically. Only one process wins per cluster. ---
let haveLock = false;
try {
  const fd = fs.openSync(LOCK_FILE, 'wx'); // fails if the file already exists
  fs.writeSync(fd, String(process.pid));
  fs.closeSync(fd);
  haveLock = true;
} catch (e) {
  // Lock exists. If its owner is alive, skip regardless of age. Only reclaim a
  // dead owner (or an old lock with no readable owner PID).
  let ownerPid = null;
  try {
    ownerPid = Number.parseInt(fs.readFileSync(LOCK_FILE, 'utf8').trim(), 10);
  } catch (_) {}
  if (isProcessAlive(ownerPid)) process.exit(0);

  let stale = false;
  try { stale = (Date.now() - fs.statSync(LOCK_FILE).mtimeMs) >= LOCK_STALE_MS; }
  catch (_) { stale = true; } // lock vanished between open and stat — race; treat as reclaimable
  if (!stale) process.exit(0);
  try {
    fs.unlinkSync(LOCK_FILE);
    const fd = fs.openSync(LOCK_FILE, 'wx');
    fs.writeSync(fd, String(process.pid));
    fs.closeSync(fd);
    haveLock = true;
  }
  catch (_) { process.exit(0); }
}

function releaseLock() {
  if (haveLock) { try { fs.unlinkSync(LOCK_FILE); } catch (_) {} haveLock = false; }
}

// Cooldown: at most one index START per COOLDOWN_MS. The lock alone only
// serialises runs — on 2026-09-28 it produced a back-to-back chain of 600s
// runs all day, each paying the full model load (2.7 GB working set, 3.1 GB
// peak) and starving the machine. Checked while holding the lock so two
// workers cannot both pass. Content from sessions inside the window waits for
// the next session end after it; the index is incremental, so nothing is lost.
const LAST_RUN_FILE = path.join(os.homedir(), '.claude', 'global-memory', 'transcripts', '.memsearch-last-run');
const COOLDOWN_MS = 30 * 60 * 1000;
try {
  if (Date.now() - fs.statSync(LAST_RUN_FILE).mtimeMs < COOLDOWN_MS) {
    releaseLock();
    process.exit(0);
  }
} catch (_) {} // no marker yet — first run
try { fs.writeFileSync(LAST_RUN_FILE, new Date().toISOString() + ` pid=${process.pid}\n`); } catch (_) {}

try {
  const res = spawnSync('memsearch', ['index', ...existing], {
    // Avoid an intermediate cmd.exe. On timeout, the direct child is killed
    // instead of leaving an orphaned Python indexer behind.
    shell: false,
    windowsHide: true,
    encoding: 'utf8',
    // memsearch can print more than Node's 1 MiB default during a large
    // incremental catch-up. Preserve its output and exit status for diagnosis.
    maxBuffer: 32 * 1024 * 1024,
    // Runaway guard, not a budget. We are detached, so nothing is waiting on
    // this. A full day's backlog measured 278s on 2026-09-02, so 600s means a
    // timeout here is a genuine hang worth escalating - not normal work being
    // cut off, which is what the old 45s cap was doing on every session end.
    timeout: 600000,
  });

  const out = `${res.stdout || ''}${res.stderr || ''}`.trim();
  const skipped = missing.length ? `(skipped, not on this machine: ${missing.join(', ')})\n` : '';

